// Paul van Laak — minimal interactions

// ---------------------------------------------------------------- i18n ----
// Interface text and project metadata live in i18n/nl.json + i18n/en.json,
// generated by build.js. The HTML ships in the default language; switching
// swaps every [data-i18n] node. Project body copy is not translated — it
// keeps its own lang attribute and a .lang-note that CSS reveals when the
// interface language differs.
const i18n = (() => {
  const root = document.documentElement;
  const BASE = root.dataset.i18nBase || '';
  const VERSION = root.dataset.i18nV || '0';
  const FALLBACK = root.dataset.langDefault || 'nl';
  const CHOICE = 'pvl-lang';
  const cacheKey = lang => `pvl-i18n-${VERSION}-${lang}`;

  // Attributes we translate, matching the data-i18n-<attr> hooks build.js emits
  const ATTRS = ['aria-label', 'aria-roledescription', 'title'];

  const read = key => { try { return localStorage.getItem(key); } catch { return null; } };
  const write = (key, value) => { try { localStorage.setItem(key, value); } catch { /* private mode */ } };

  function cached(lang) {
    const raw = read(cacheKey(lang));
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return null; }
  }

  function cache(lang, dict) {
    // Drop dictionaries from older builds so the key never grows unbounded
    try {
      for (let i = localStorage.length - 1; i >= 0; i--) {
        const key = localStorage.key(i);
        if (key?.startsWith('pvl-i18n-') && !key.startsWith(`pvl-i18n-${VERSION}-`)) localStorage.removeItem(key);
      }
    } catch { /* ignore */ }
    write(cacheKey(lang), JSON.stringify(dict));
  }

  function apply(dict) {
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const value = dict[el.dataset.i18n];
      if (value != null) el.textContent = value;
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      const value = dict[el.dataset.i18nHtml];
      if (value != null) el.innerHTML = value;
    });
    ATTRS.forEach(attr => {
      const hook = `data-i18n-${attr}`;
      document.querySelectorAll(`[${hook}]`).forEach(el => {
        const value = dict[el.getAttribute(hook)];
        if (value != null) el.setAttribute(attr, value);
      });
    });
  }

  function paint(lang, dict) {
    root.lang = lang;
    root.dataset.lang = lang;              // drives .lang-note visibility
    if (dict) apply(dict);
    document.querySelectorAll('[data-lang-set]').forEach(btn =>
      btn.setAttribute('aria-pressed', String(btn.dataset.langSet === lang)));
  }

  function activate(lang, persist) {
    const hit = cached(lang);
    if (hit) {                              // synchronous — no flash of the wrong language
      paint(lang, hit);
      if (persist) write(CHOICE, lang);
      return;
    }
    fetch(`${BASE}${lang}.json`)
      .then(res => (res.ok ? res.json() : Promise.reject(res.status)))
      .then(dict => {
        cache(lang, dict);
        paint(lang, dict);
        if (persist) write(CHOICE, lang);
      })
      // Offline, or opened over file:// where fetch is blocked — stay put
      .catch(() => {});
  }

  document.querySelectorAll('[data-lang-set]').forEach(btn =>
    btn.addEventListener('click', () => activate(btn.dataset.langSet, true)));

  const stored = read(CHOICE);
  const wanted = stored === 'nl' || stored === 'en' ? stored : FALLBACK;
  // The page is already rendered in FALLBACK, so that case needs no dictionary
  if (wanted === FALLBACK) paint(wanted);
  else activate(wanted, false);

  return { activate };
})();

// Mobile menu
const menuBtn = document.getElementById('menu-btn');
const nav = document.getElementById('main-nav');
if (menuBtn && nav) {
  menuBtn.addEventListener('click', () => {
    const open = nav.classList.toggle('open');
    menuBtn.setAttribute('aria-expanded', String(open));
  });
  nav.querySelectorAll('a').forEach(a =>
    a.addEventListener('click', () => {
      nav.classList.remove('open');
      menuBtn.setAttribute('aria-expanded', 'false');
    })
  );
}

// Work rail arrows — scoped per section so a page can hold more than one rail
document.querySelectorAll('[data-rail]').forEach(rail => {
  const section = rail.closest('section') || document;
  const step = () => Math.round(rail.clientWidth * 0.7);
  section.querySelector('[data-rail-prev]')?.addEventListener('click', () =>
    rail.scrollBy({ left: -step(), behavior: 'smooth' }));
  section.querySelector('[data-rail-next]')?.addEventListener('click', () =>
    rail.scrollBy({ left: step(), behavior: 'smooth' }));
});

// Project photo carousel.
// The markup is a plain horizontal scroll-snap track, so it still works without
// this script; here we add arrows, a counter and the dot index on top of it.
document.querySelectorAll('[data-carousel]').forEach(root => {
  const track = root.querySelector('[data-carousel-track]');
  const slides = [...track.querySelectorAll('.carousel-slide')];
  if (slides.length < 2) return;

  const prev = root.querySelector('[data-carousel-prev]');
  const next = root.querySelector('[data-carousel-next]');
  const count = root.querySelector('[data-carousel-count]');
  const dots = [...root.querySelectorAll('[data-carousel-dot]')];
  const smooth = matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';

  // `current` is the source of truth: the controls update straight away and the
  // scroll listener only reconciles it after a swipe or a trackpad scroll.
  let current = 0;
  const clamp = i => Math.min(Math.max(i, 0), slides.length - 1);

  const render = () => {
    count.textContent = `${current + 1} / ${slides.length}`;
    prev.disabled = current === 0;
    next.disabled = current === slides.length - 1;
    dots.forEach((dot, n) => dot.setAttribute('aria-current', String(n === current)));
  };

  const go = (i, behavior = smooth) => {
    current = clamp(i);
    render();
    track.scrollTo({ left: current * track.clientWidth, behavior });
  };

  prev.addEventListener('click', () => go(current - 1));
  next.addEventListener('click', () => go(current + 1));
  dots.forEach((dot, n) => dot.addEventListener('click', () => go(n)));

  track.addEventListener('keydown', e => {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    e.preventDefault();
    go(current + (e.key === 'ArrowRight' ? 1 : -1));
  });

  let settle;
  track.addEventListener('scroll', () => {
    clearTimeout(settle);
    settle = setTimeout(() => {
      const i = clamp(Math.round(track.scrollLeft / track.clientWidth));
      if (i === current) return;
      current = i;
      render();
    }, 90);
  }, { passive: true });

  // Keep the active slide framed when the column width changes
  addEventListener('resize', () => go(current, 'auto'));

  render();
});

// Fade-in on scroll
const io = 'IntersectionObserver' in window
  ? new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          e.target.style.opacity = 1;
          e.target.style.transform = 'none';
          io.unobserve(e.target);
        }
      });
    }, { threshold: 0.12 })
  : null;
// .pdp is skipped: an animated transform on it would break the sticky info column.
if (io && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
  document.querySelectorAll('section:not(.hero):not(.pdp)').forEach(el => {
    el.style.opacity = 0;
    el.style.transform = 'translateY(24px)';
    el.style.transition = 'opacity .8s ease, transform .8s ease';
    io.observe(el);
  });
}

// Footer year
document.querySelectorAll('[data-year]').forEach(el => (el.textContent = new Date().getFullYear()));
